import { WORLD_LS_KEYS, readWorldJson, writeWorldJson } from './world-store';
const DEFAULT_PROFILE = {
    nickname: '我', following: 0, followers: 0, ipLocation: 'IP属地：未知', verifyText: '微博个人认证', level: 1,
};
const DEFAULT_SETTINGS = {
    useWorldbook: false, worldbookIds: [], autoEnabled: false, autoInterval: 20, lastFloor: 0,
    feedScope: 'recommend', timelineMode: 'world',
    ecoActivity: 60, ecoControl: 40, ecoSnark: 50, ecoErotic: 30, ecoCarnal: 40, blockWords: [], antiSpoiler: true, echoEnabled: true,
    syncEnabled: false, memoryEnabled: true, worldAnchorText: '', worldAnchorTs: 0, // 世界书同步默认关
    useFloors: true, floorCount: 6,
};
function rid(p) { return `${p}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`; }
function read() {
    const d = readWorldJson(WORLD_LS_KEYS.weibo, { posts: [], hots: [] });
    if (!d || typeof d !== 'object')
        return { posts: [], hots: [], notifies: [], follows: [], supers: [] };
    if (!Array.isArray(d.posts))
        d.posts = [];
    if (!Array.isArray(d.hots))
        d.hots = [];
    if (!Array.isArray(d.notifies))
        d.notifies = [];
    if (!Array.isArray(d.follows))
        d.follows = [];
    if (!Array.isArray(d.supers))
        d.supers = [];
    d.profile = { ...DEFAULT_PROFILE, ...(d.profile || {}) };
    d.settings = { ...DEFAULT_SETTINGS, ...(d.settings || {}) };
    return d;
}
function write(d) { writeWorldJson(WORLD_LS_KEYS.weibo, d); }
// ---------- 微博 ----------
export function getPosts() {
    return read().posts.slice().sort((a, b) => b.ts - a.ts);
}
export function getPostsByAuthorRef(ref) {
    return getPosts().filter(p => p.authorRef === ref);
}
export function getPost(id) { return read().posts.find(p => p.id === id); }
export function createPost(p) {
    const d = read();
    const post = {
        id: p.id || rid('wb'),
        author: p.author, authorRef: p.authorRef, content: p.content,
        image: p.image, imgDesc: p.imgDesc, imgTags: p.imgTags, imgList: p.imgList,
        ts: Date.now(), likes: p.likes ?? 0, liked: p.liked, reposts: p.reposts ?? 0,
        fans: p.fans, verified: p.verified, ip: p.ip, device: p.device,
        repostOf: p.repostOf, quoteOf: p.quoteOf, topic: p.topic, poll: p.poll,
        isAi: !!p.isAi, comments: [],
    };
    d.posts.push(post);
    write(d);
    return post;
}
export function deletePost(id) {
    const d = read();
    d.posts = d.posts.filter(p => p.id !== id);
    write(d);
}
export function updatePost(id, patch) {
    const d = read();
    const p = d.posts.find(x => x.id === id);
    if (!p)
        return;
    Object.assign(p, patch);
    write(d);
}
export function togglePostLike(id) {
    const d = read();
    const p = d.posts.find(x => x.id === id);
    if (!p)
        return;
    if (p.liked) {
        p.liked = false;
        p.likes = Math.max(0, (p.likes || 0) - 1);
    }
    else {
        p.liked = true;
        p.likes = (p.likes || 0) + 1;
    }
    write(d);
}
// 给投票博文投一票（idx=选项下标）。已投过则改投。
export function votePoll(postId, idx) {
    const d = read();
    const p = d.posts.find(x => x.id === postId);
    if (!p || !p.poll || !p.poll.options[idx])
        return;
    const prev = p.poll.myVote;
    if (prev === idx)
        return;
    if (typeof prev === 'number' && p.poll.options[prev])
        p.poll.options[prev].votes = Math.max(0, (p.poll.options[prev].votes || 0) - 1);
    p.poll.options[idx].votes = (p.poll.options[idx].votes || 0) + 1;
    p.poll.myVote = idx;
    write(d);
}
export function repost(id, byAuthor, comment) {
    const d = read();
    const src = d.posts.find(x => x.id === id);
    if (!src)
        return undefined;
    src.reposts = (src.reposts || 0) + 1;
    const rp = {
        id: rid('wb'), author: byAuthor, content: comment || '转发微博',
        ts: Date.now(), likes: 0, reposts: 0, repostOf: id, comments: [],
    };
    d.posts.push(rp);
    write(d);
    return rp;
}
// ---------- 评论 ----------
export function addComment(postId, c) {
    const d = read();
    const p = d.posts.find(x => x.id === postId);
    if (!p)
        return undefined;
    const cm = { id: rid('cm'), author: c.author, authorRef: c.authorRef, content: c.content, ts: Date.now(), likes: 0, ip: c.ip, replyTo: c.replyTo, isAi: !!c.isAi, toMe: c.toMe };
    p.comments.push(cm);
    write(d);
    return cm;
}
export function deleteComment(postId, commentId) {
    const d = read();
    const p = d.posts.find(x => x.id === postId);
    if (!p)
        return;
    p.comments = p.comments.filter(c => c.id !== commentId);
    write(d);
}
export function toggleCommentLike(postId, commentId) {
    const d = read();
    const p = d.posts.find(x => x.id === postId);
    if (!p)
        return;
    const c = p.comments.find(x => x.id === commentId);
    if (!c)
        return;
    if (c.liked) {
        c.liked = false;
        c.likes = Math.max(0, (c.likes || 0) - 1);
    }
    else {
        c.liked = true;
        c.likes = (c.likes || 0) + 1;
    }
    write(d);
}
// ---------- 热搜 ----------
export function getHots() {
    return read().hots.slice().sort((a, b) => b.heat - a.heat);
}
export function setHots(items) {
    const d = read();
    d.hots = items.filter(x => x.keyword && x.keyword.trim()).map((x, i) => ({
        id: rid('ht'), keyword: x.keyword.trim(),
        heat: x.heat ?? (1000000 - i * 50000 + Math.floor(Math.random() * 30000)),
        tag: x.tag, desc: x.desc, ts: Date.now(),
    }));
    write(d);
}
export function clearAll() {
    const d = read();
    // 保留个人资料/设置/关注/超话（偏好类），只清内容流与通知
    write({ posts: [], hots: [], profile: d.profile, settings: d.settings, follows: d.follows, supers: d.supers, notifies: [] });
}
// 覆盖刷新：清掉 AI 路人博文后再生成。保留「我」发的、点过赞的、有评论的，避免丢数据。
export function clearFeedPosts() {
    const d = read();
    d.posts = d.posts.filter(p => !p.isAi || p.liked || (Array.isArray(p.comments) && p.comments.length > 0));
    write(d);
}
// ---------- 我的动态 / 个人资料 / 设置 ----------
// 「我」发布的微博（author 非 AI）。
export function getMyPosts() { return getPosts().filter(p => !p.isAi); }
export function getProfile() {
    const d = read();
    const p = d.profile || DEFAULT_PROFILE;
    // 关注数以真实关注名单为唯一事实来源，避免「显示 25 但名单为空」的脱节。
    const following = (d.follows || []).length;
    return { ...p, following };
}
export function updateProfile(patch) {
    const d = read();
    d.profile = { ...DEFAULT_PROFILE, ...(d.profile || {}), ...patch };
    write(d);
}
export function getMyPostCount() { return getMyPosts().length; }
// 粉丝/等级成长：按互动量（发博、被评论/被@）真实回写 profile.followers/level/verified。
//   兑现「粉丝数会在 AI 生成时按剧情自动浮动」的承诺——只加不减、带随机波动，避免机械。
//   verified：粉丝破阈值自动解锁一档认证文案（玩家已手填则不覆盖）。
export function bumpFollowers(delta, reason) {
    if (!delta)
        return;
    const d = read();
    const p = { ...DEFAULT_PROFILE, ...(d.profile || {}) };
    const jitter = reason === 'post' ? Math.floor(Math.random() * 60) : Math.floor(Math.random() * 20);
    p.followers = Math.max(0, (p.followers || 0) + Math.max(0, delta) + jitter);
    // 等级：按粉丝对数增长，1~10 档
    p.level = Math.max(1, Math.min(10, Math.floor(Math.log10(Math.max(1, p.followers)) * 1.6) + 1));
    // 认证：粉丝破线自动解锁（玩家未手填时）
    if (!p.verified) {
        if (p.followers >= 100000)
            p.verified = '知名博主';
        else if (p.followers >= 10000)
            p.verified = '微博原创作者';
    }
    d.profile = p;
    write(d);
}
export function getSettings() {
    return read().settings || DEFAULT_SETTINGS;
}
export function updateSettings(patch) {
    const d = read();
    d.settings = { ...DEFAULT_SETTINGS, ...(d.settings || {}), ...patch };
    write(d);
}
export function clearAllData() { const d = read(); write({ posts: [], hots: [], profile: d.profile, settings: d.settings }); }
// ==================== 通知中心 ====================
export function getNotifies() { return (read().notifies || []).slice().sort((a, b) => b.ts - a.ts); }
export function getUnreadNotifyCount() { return (read().notifies || []).filter(n => !n.read).length; }
export function addNotify(n) {
    const d = read();
    (d.notifies ||= []).push({ id: rid('nt'), kind: n.kind, actor: n.actor, actorRef: n.actorRef, text: n.text, postId: n.postId, ts: Date.now(), read: false });
    if (d.notifies.length > 200)
        d.notifies = d.notifies.slice(-200);
    write(d);
}
export function markAllNotifyRead() {
    const d = read();
    (d.notifies || []).forEach(n => { n.read = true; });
    write(d);
}
export function clearNotifies() { const d = read(); d.notifies = []; write(d); }
// ==================== 关注关系 + 关注流 ====================
export function getFollows() { return (read().follows || []).slice(); }
export function isFollowing(name) { return (read().follows || []).some(f => f.name === name); }
export function toggleFollow(name, ref) {
    const d = read();
    const list = (d.follows ||= []);
    const i = list.findIndex(f => f.name === name);
    let nowFollowing;
    if (i >= 0) {
        list.splice(i, 1);
        nowFollowing = false;
    }
    else {
        list.push({ name, ref, ts: Date.now() });
        nowFollowing = true;
    }
    // 关注数由 getProfile 从 follows.length 实时派生，这里不再手动加减（避免双计/脱节）。
    write(d);
    return nowFollowing;
}
// 某博主的全部博文（主页用）
export function getPostsByAuthor(name) { return getPosts().filter(p => p.author === name); }
// ==================== 超话 / CP 超话 ====================
export function getSupers() { return (read().supers || []).slice().sort((a, b) => (b.posts || 0) - (a.posts || 0)); }
export function getSuper(id) { return (read().supers || []).find(s => s.id === id); }
export function upsertSupers(items) {
    const d = read();
    const list = (d.supers ||= []);
    for (const it of items) {
        if (!it.name || !it.name.trim())
            continue;
        const name = it.name.trim();
        const ex = list.find(s => s.name === name);
        if (ex) {
            ex.kind = it.kind || ex.kind;
            ex.desc = it.desc ?? ex.desc;
            ex.posts = it.posts ?? ex.posts;
        }
        else
            list.push({ id: rid('sup'), name, kind: it.kind || 'topic', desc: it.desc, posts: it.posts ?? 0, followed: false, ts: Date.now() });
    }
    write(d);
}
export function toggleSuperFollow(id) {
    const d = read();
    const s = (d.supers || []).find(x => x.id === id);
    if (!s)
        return false;
    s.followed = !s.followed;
    write(d);
    return !!s.followed;
}
// 生成本超话讨论后，把展示帖量往上抬（真实感：讨论越多帖量越大）。
export function bumpSuperPosts(id, delta) {
    const d = read();
    const s = (d.supers || []).find(x => x.id === id);
    if (!s)
        return;
    s.posts = Math.max(0, (s.posts || 0) + delta);
    write(d);
}
export function deleteSuper(id) {
    const d = read();
    d.supers = (d.supers || []).filter(s => s.id !== id);
    write(d);
}
