import { getRoot } from '../tavern-api';

function getFn<T = any>(name: string): T | null {
  try {
    const w = window as any;
    if (typeof w[name] === 'function') return w[name] as T;
    const r = getRoot() as any;
    if (r && typeof r[name] === 'function') return r[name] as T;
  } catch (e) { void e; }
  return null;
}

export type WbEntryLite = { uid: number; name: string; content: string; enabled: boolean };

// 所有世界书名（含全局/角色卡/聊天绑定的并集，去重）。
export function listWorldbookNames(): string[] {
  const names = new Set<string>();
  try {
    const all = getFn<() => string[]>('getWorldbookNames')?.() || [];
    all.forEach(n => n && names.add(n));
  } catch (e) { void e; }
  // 兜底：把当前角色卡/全局绑定的也并进来（有些环境 getWorldbookNames 只回已加载的）
  try {
    const g = getFn<() => string[]>('getGlobalWorldbookNames')?.() || [];
    g.forEach(n => n && names.add(n));
  } catch (e) { void e; }
  try {
    const cw = getFn<(c: string) => { primary: string | null; additional: string[] }>('getCharWorldbookNames')?.('current');
    if (cw) { if (cw.primary) names.add(cw.primary); (cw.additional || []).forEach(n => n && names.add(n)); }
  } catch (e) { void e; }
  return [...names];
}

// 某本世界书的条目（轻量）。异步：getWorldbook 返回 Promise。
export async function listWorldbookEntries(book: string): Promise<WbEntryLite[]> {
  const fn = getFn<(b: string) => Promise<any[]>>('getWorldbook');
  if (!fn || !book) return [];
  try {
    const entries = await fn(book);
    if (!Array.isArray(entries)) return [];
    return entries.map((e: any) => ({
      uid: Number(e?.uid ?? -1),
      name: String(e?.name ?? '') || `条目#${e?.uid ?? '?'}`,
      content: String(e?.content ?? ''),
      enabled: !!e?.enabled,
    }));
  } catch (e) { void e; return []; }
}

export function isWorldbookAvailable(): boolean {
  return !!getFn('getWorldbookNames') || !!getFn('getWorldbook');
}

// 选择以 `${book}<U+241F>${entryName}` 为 key（单元分隔符须可打印，NUL 会被 JSON 往返损坏成 U+FFFD）。
const KEY_SEP = '␟';
const LEGACY_SEPS = ['\u0000', '�'];
export function wbEntryKey(book: string, entry: string): string { return `${book}${KEY_SEP}${entry}`; }
export function parseWbEntryKey(key: string): { book: string; entry: string } {
  let i = key.indexOf(KEY_SEP);
  if (i < 0) { for (const sep of LEGACY_SEPS) { const j = key.indexOf(sep); if (j >= 0) { i = j; break; } } }
  if (i < 0) return { book: key, entry: '' };
  return { book: key.slice(0, i), entry: key.slice(i + 1) };
}
// 把任意(含历史损坏)key 规整成当前标准分隔符的 key。已是标准格式则原样返回。
export function normalizeEntryKey(key: string): string {
  if (key.indexOf(KEY_SEP) >= 0) return key;
  const { book, entry } = parseWbEntryKey(key);
  return entry ? wbEntryKey(book, entry) : key;
}

// 条目缓存：同一 sheet 内多次展开/勾选不重复请求。
const _entryCache: Record<string, WbEntryLite[]> = {};
export async function loadEntriesCached(book: string): Promise<WbEntryLite[]> {
  if (_entryCache[book]) return _entryCache[book];
  const e = await listWorldbookEntries(book);
  _entryCache[book] = e;
  return e;
}
export function clearEntryCache(): void { for (const k of Object.keys(_entryCache)) delete _entryCache[k]; }

// 由「条目 key 列表」拼装注入文本（按书分组；只取仍存在且非禁用的条目）。
export async function buildInjectFromKeys(keys: string[]): Promise<string> {
  if (!keys.length) return '';
  // 按书分组
  const byBook: Record<string, Set<string>> = {};
  for (const k of keys) { const { book, entry } = parseWbEntryKey(k); if (!book) continue; (byBook[book] ||= new Set()).add(entry); }
  const chunks: string[] = [];
  for (const book of Object.keys(byBook)) {
    try {
      const entries = await loadEntriesCached(book);
      const wanted = byBook[book];
      const body = entries
        .filter(e => wanted.has(e.name) && e.enabled !== false)
        .map(e => String(e.content || '').trim())
        .filter(Boolean)
        .join('\n---\n');
      if (body) chunks.push(`【${book}】\n${body}`);
    } catch (e) { void e; }
  }
  return chunks.join('\n\n');
}

// 按条目名跨所有世界书解析出引用（用于预设/地点自动绑定）。
// names 支持精确名或「包含匹配」（如传 "霜月仙宗设定" 命中同名条目；传 "甘霖天池" 命中所有含该串的地点条目）。
// 返回 { book, uid, name }[]，与 EvoWbRef 结构兼容；找不到则跳过。
export async function resolveWbRefsByName(names: string[], opts?: { contains?: boolean }): Promise<{ book: string; uid: number; name: string }[]> {
  if (!names.length || !isWorldbookAvailable()) return [];
  const books = listWorldbookNames();
  const out: { book: string; uid: number; name: string }[] = [];
  const seen = new Set<string>();
  for (const book of books) {
    let entries: WbEntryLite[] = [];
    try { entries = await loadEntriesCached(book); } catch (e) { void e; continue; }
    for (const want of names) {
      for (const e of entries) {
        const hit = opts?.contains ? e.name.includes(want) : e.name === want;
        if (!hit) continue;
        const k = `${book}${KEY_SEP}${e.name}`;
        if (seen.has(k)) continue;
        seen.add(k);
        out.push({ book, uid: e.uid, name: e.name });
      }
    }
  }
  return out;
}

// 调试挂载
try {
  const w = (typeof window !== 'undefined' ? window : globalThis) as any;
  w.__th_world_worldbook__ = { listWorldbookNames, listWorldbookEntries, isWorldbookAvailable, resolveWbRefsByName };
} catch (e) { void e; }
